import "core-js/modules/web.dom.iterable";
import { globalattrDetail, globalattrSave } from "@/api/system/relationManage";
import { attrrelSearch } from "@/api/cmdb/ciConfig";
export default {
  props: ['isShow', 'ciId', 'showType'],
  data: function data() {
    return {
      attrRelList: []
    };
  },
