    this.getDetail();
  },
  methods: {
    // 详情
    getDetail: function getDetail() {
      var _this = this;
      attrrelSearch({
        ciId: this.ciId
      }).then(function (res) {
        _this.attrRelList = res.Return;
      });
    },
    selectExportItem: function selectExportItem(item) {
      this.$set(item, 'selected', !item.selected);
    },
    selectAllExportItem: function selectAllExportItem() {
      var _this2 = this;
      this.attrRelList.forEach(function (element) {
        _this2.$set(element, 'selected', true);
      });
    },
    // 保存
    save: function save() {
      var selectArr = this.attrRelList.filter(function (el) {
